ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
  statusUpdate: {
    taskId: vars.task_id,
    contextId: vars.contextId,
    status: {
      state: "TASK_STATE_COMPLETED",
      message: {
        messageId: uuid(),
        role: "ROLE_AGENT",
        parts: [{ text: payload.choices[0].message.content }]
      },
      timestamp: (now() >> "UTC") as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
    }
  }
}

%dw 2.0
output application/json
---
{
  messages: vars.convMessages.messages ++ [
    { role: "assistant", content: payload.choices[0].message.content }
  ]
}

%dw 2.0

output application/json

var updatedHistory = 
vars.conversationHistory.messages + { role: "user", "content" : vars.user_prompt }

---
{
  messages:
    (if (sizeOf(updatedHistory) > 10) 
    	updatedHistory[-10 to -1] 
     else updatedHistory
    )
}

%dw 2.0 output application/json
--- {
messages: [{ role: "user", content: readUrl(vars.systemPromptPath, "text/plain") ++ "\n" ++ (vars.user_prompt default "") }]
}
